(R/'assets/campaign.css').write_text(style)
def inline(x):
 x=e(x)
 x=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',x)
 x=re.sub(r'(?<!\*)\*([^*]+)\*(?!\*)',r'<em>\1</em>',x)
 return re.sub(r'\[([^]]+)\]\(([^)]+)\)',r'<a href="\2">\1</a>',x)
def markdown(s):
 result=[]
 for block in s.strip().split('\n\n'):
  image=re.fullmatch(r'!\[([^]]*)\]\(([^)]+)\)',block)
  if image:result.append(f'<a href="{e(image[2])}"><img loading="lazy" src="{e(image[2])}" alt="{e(image[1])}"></a>');continue
  if block.startswith('## '):result.append('<h2>'+inline(block[3:])+'</h2>');continue
  result.append('<p>'+inline(block)+'</p>')
 return '\n'.join(result)
def doc(title,body):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+'</title><link rel="stylesheet" href="assets/campaign.css"></head><body>'+body+'</body></html>'
meta=json.loads((R/'blog-metadata.json').read_text());body=(R/'blog-body.md').read_text()
(R/'blog-preview.html').write_text(doc(meta['title'],'<article class="blog"><div class="review">Prepared for owner review. This local preview does not publish the article.</div><p class="eyebrow">JOBSEAM · A QUEZAAL INC. PRODUCT</p><h1>'+e(meta['title'])+'</h1>'+markdown(body)+'</article>'))
base='https://jobseam.com/campaigns/2026-11-connected-recruiting/'
public=re.sub(r'\]\((assets/[^)]+|screenshot-flyer.pdf)\)',lambda m:']('+base+m[1]+')',body)
