def foot(n):return f'<footer class="footer"><span>A Quezaal Inc. product · Sample product views · November 12, 2026</span><span>{n} / 2</span></footer>'
def shot(name,alt,cls='screen-main'):return '<img class="screenshot '+cls+'" src="assets/'+name+'" alt="'+e(alt)+'">'
